def lines(s: str, width: int, max_lines: int = 2) -> list[str]:
    wrapped = textwrap.wrap(s, width, break_long_words=False, break_on_hyphens=False)
    if len(wrapped) > max_lines:
        raise ValueError(f'text too long for map: {s!r} -> {wrapped}')
    return wrapped or ['']


def svg(d: dict, lang: str) -> str:
    idx = LANGS.index(lang)
    title = d['title'][idx]
    if d['n'] in (67, 68):
        return svg_chart(d, lang)
    # The first label tuple is the Kazakh support signal shared by all lessons;
    # the second is its Russian map translation.
    label = d['labels'][{'ru': 1, 'kz': 0, 'en': 2}[lang]]
    title_lines = lines(title, 52, 2)
    colors = ['#187b95', '#c06541', '#705dab', '#25836e']
    title_text = ''.join(f'<text x="90" y="{155+i*55}" font-size="40" font-weight="800" fill="#18354b">{html.escape(t)}</text>' for i,t in enumerate(title_lines))
    cards = []
    for i, lab in enumerate(label):
        x=72+i*375; y=315
        label_text=''.join(f'<text x="{x+160}" y="{y+145+j*39}" text-anchor="middle" font-size="26" font-weight="700" fill="#18354b">{html.escape(t)}</text>' for j,t in enumerate(lines(lab,19)))
        example_text=''.join(f'<text x="{x+160}" y="{y+239+j*28}" text-anchor="middle" font-size="21" fill="#526b79">{html.escape(t)}</text>' for j,t in enumerate(lines(MAP_EXAMPLES[d['n']][lang][i],24)))
        cards.append(f'<g filter="url(#shadow)"><rect x="{x}" y="{y}" width="320" height="303" rx="16" fill="#fff" stroke="{colors[i]}" stroke-width="4"/><rect x="{x}" y="{y}" width="320" height="55" rx="14" fill="{colors[i]}"/><text x="{x+25}" y="{y+39}" font-size="27" fill="#fff" font-weight="800">0{i+1}</text>{label_text}<path d="M{x+30} {y+210}h260" stroke="#d8e2e6" stroke-width="2"/>{example_text}</g>')
    arrows=''.join(f'<path d="M{72+i*375+330} 466h35"/>' for i in range(3))
    caption={'ru':'НАБЛЮДАЙ  /  ПРОВЕРЯЙ  /  ОБЪЯСНЯЙ','kz':'БАЙҚА  /  ТЕКСЕР  /  ТҮСІНДІР','en':'OBSERVE  /  CHECK  /  EXPLAIN'}[lang]
    heading={'ru':'ОПОРНАЯ КАРТА','kz':'ТІРЕК КАРТА','en':'SUPPORT MAP'}[lang]
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 900" role="img" aria-label="{html.escape(title)}"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#d0e5e9"/></pattern><filter id="shadow" x="-15%" y="-20%" width="135%" height="150%"><feDropShadow dx="0" dy="10" stdDeviation="12" flood-color="#17364e" flood-opacity=".19"/></filter><marker id="arrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0 0L9 4.5L0 9Z" fill="#2e5a72"/></marker></defs><rect width="1600" height="900" fill="#eaf5f8"/><rect width="1600" height="900" fill="url(#grid)"/><rect x="42" y="42" width="1516" height="816" rx="26" fill="#f8fcfd" stroke="#bfd6df" stroke-width="3"/><g font-family="DejaVu Sans,Arial,sans-serif"><text x="90" y="102" font-size="27" font-weight="800" fill="#b94741">{heading} · {d['n']}</text>{title_text}{''.join(cards)}<g fill="none" stroke="#2e5a72" stroke-width="5" marker-end="url(#arrow)">{arrows}</g><rect x="390" y="755" width="820" height="50" rx="14" fill="#17364e"/><text x="800" y="789" text-anchor="middle" font-size="23" font-weight="700" fill="#fff">{caption}</text></g></svg>'''


def svg_chart(d: dict, lang: str) -> str:
    """The data lessons show proportional bars, not merely words about bars."""
    n=d['n']; idx=LANGS.index(lang); title=d['title'][idx]
    title_text=''.join(f'<text x="90" y="{155+i*52}" font-size="38" font-weight="800" fill="#18354b">{html.escape(t)}</text>' for i,t in enumerate(lines(title,55,2)))
    heading={'ru':'ОПОРНАЯ КАРТА','kz':'ТІРЕК КАРТА','en':'SUPPORT MAP'}[lang]
    unit={'ru':'человек','kz':'адам','en':'people'}[lang]
    note1={'ru':'Шкала начинается с нуля','kz':'Шкала нөлден басталады','en':'The scale starts at zero'}[lang]
    if n==67:
        days={'ru':('ПН','ВТ','СР'),'kz':('ДС','СС','СР'),'en':('MON','TUE','WED')}[lang]
        values=(12,18,15)
        note2={'ru':'Только три дня','kz':'Тек үш күн','en':'Three days only'}[lang]
        note3={'ru':'Высота ≠ причина','kz':'Биіктік ≠ себеп','en':'Height ≠ cause'}[lang]
        xs=(365,565,765)
        bars=''.join(f'<g filter="url(#shadow)"><rect x="{x}" y="{650-v*17}" width="105" height="{v*17}" rx="7" fill="{("#187b95","#c06541","#705dab")[i]}"/></g><text x="{x+52}" y="{640-v*17}" text-anchor="middle" font-size="29" font-weight="800" fill="#18354b">{v}</text><text x="{x+52}" y="695" text-anchor="middle" font-size="25" font-weight="700" fill="#18354b">{days[i]}</text>' for i,(x,v) in enumerate(zip(xs,values)))
    else:
        days={'ru':('ПН','ВТ'),'kz':('ДС','СС'),'en':('MON','TUE')}[lang]
        note2={'ru':'+6 от исходных 12 = +50%','kz':'12-мен салыстырғанда +6 = +50%','en':'+6 versus 12 = +50%'}[lang]
        note3={'ru':'Не вдвое: 2 × 12 = 24','kz':'Екі есе емес: 2 × 12 = 24','en':'Not double: 2 × 12 = 24'}[lang]
        bars='<g filter="url(#shadow)"><rect x="430" y="446" width="135" height="204" rx="8" fill="#187b95"/><rect x="680" y="446" width="135" height="204" rx="8" fill="#187b95"/><rect x="680" y="344" width="135" height="102" rx="8" fill="#c06541"/></g><text x="497" y="432" text-anchor="middle" font-size="29" font-weight="800" fill="#18354b">12</text><text x="747" y="330" text-anchor="middle" font-size="29" font-weight="800" fill="#18354b">18</text><text x="497" y="695" text-anchor="middle" font-size="25" font-weight="700" fill="#18354b">'+days[0]+'</text><text x="747" y="695" text-anchor="middle" font-size="25" font-weight="700" fill="#18354b">'+days[1]+'</text><text x="834" y="403" font-size="27" font-weight="800" fill="#c06541">+6</text>'
    grid=''.join(f'<path d="M250 {650-v*17}H925" stroke="#dce8ed" stroke-width="2"/><text x="225" y="{658-v*17}" text-anchor="end" font-size="22" fill="#536d7b">{v}</text>' for v in (0,5,10,15,20))
    note_lines=[note1,note2,note3]
    notes=''.join(f'<text x="1038" y="{378+i*100}" font-size="23" fill="#17364e" font-weight="700">{html.escape(t)}</text>' for i,t in enumerate(note_lines))
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 900" role="img" aria-label="{html.escape(title)}"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#d0e5e9"/></pattern><filter id="shadow" x="-15%" y="-20%" width="135%" height="150%"><feDropShadow dx="0" dy="9" stdDeviation="9" flood-color="#17364e" flood-opacity=".17"/></filter></defs><rect width="1600" height="900" fill="#eaf5f8"/><rect width="1600" height="900" fill="url(#grid)"/><rect x="42" y="42" width="1516" height="816" rx="26" fill="#f8fcfd" stroke="#bfd6df" stroke-width="3"/><g font-family="DejaVu Sans,Arial,sans-serif"><text x="90" y="102" font-size="27" font-weight="800" fill="#b94741">{heading} · {n}</text>{title_text}<rect x="170" y="280" width="800" height="455" rx="18" fill="#fff" stroke="#c7dce5" stroke-width="3"/>{grid}<path d="M250 310V650H925" fill="none" stroke="#32566a" stroke-width="4"/>{bars}<text x="260" y="291" font-size="21" fill="#526b79">{unit}</text><rect x="1005" y="290" width="490" height="360" rx="18" fill="#fff" stroke="#25836e" stroke-width="3" filter="url(#shadow)"/>{notes}<rect x="430" y="770" width="740" height="42" rx="12" fill="#17364e"/><text x="800" y="798" text-anchor="middle" font-size="22" font-weight="700" fill="#fff">{html.escape('12 → 18 → 15' if n==67 else '12 → 18  |  +6  |  +50%')}</text></g></svg>'''


def render(d: dict, lang: str, next_d: dict | None, by_phrase: dict) -> str:
    idx=LANGS.index(lang); ui=UI[lang]; c=COMMON[lang]
    parts=[f"# {d['title'][idx]}", '', f"_Lead (summary):_ **{d['lead'][idx]}**",'',f'## {ui[0]}','',c['map'],'',f"![{d['title'][idx]}](/static/course/kazakh-language/map-{d['map']}-{lang}.svg)",'',f'## {ui[1]}','',d['scene'][idx],'',f'## {ui[2]}','']
    for phrase,ru,kz,en in d['phrases']:
        parts += [f"[{ui[16]}: {phrase}](/static/course/kazakh-language/audio/{by_phrase[phrase]['file']}) — {(ru,kz,en)[idx]}",'']
    sections=[(ui[3],c['listen']),(ui[4],d['model'][idx]),(ui[5],'```kazakh\n'+' → '.join(d['labels'][0])+'\n```'),(ui[6],d['limit'][idx]),(ui[7],c['predict']),(ui[8],c['recall']),(ui[9],d['error'][idx]),(ui[10],d['transfer'][idx]),(ui[11],c['project']+' '+d['project'][idx]),(ui[12],d['task'][idx])]
    for heading,body in sections:parts += [f'## {heading}','',body,'']
    parts += [f'## {ui[13]}','',*('- '+x for x in c['repeat'])]
    if next_d:parts += ['',f"[{ui[14]}: {next_d['title'][idx]}](/read/kazakh-language-{next_d['n']:02d}-{next_d['slug']}?lang={lang})"]
    else:parts += ['',f'[{ui[15]}](/course/kazakh-language?lang={lang})']
    return '\n'.join(parts)+'\n'


def main():
    assert [d['n'] for d in LESSONS] == list(range(65,73))
    data=json.loads((AUDIO/'manifest.json').read_text(encoding='utf-8'))
    rows=data['recordings'];by_phrase={r['phrase']:r for r in rows}
    next_id=max(int(r['id'][3:]) for r in rows)+1
    for d in LESSONS:
        stem=f"{d['n']:02d}-{d['slug']}"
        for phrase,*_ in d['phrases']:
            row=by_phrase.get(phrase)
            if row is None:
                row={'id':f'kz-{next_id:03d}','phrase':phrase,'file':f'kz-{next_id:03d}.wav','status':'candidate_review','lessons':[]}
                rows.append(row);by_phrase[phrase]=row;next_id+=1
            for lang in LANGS:
                name=stem+('' if lang=='ru' else '-'+lang)+'.md'
                if name not in row['lessons']:row['lessons'].append(name)
            row['lessons'].sort()
    (AUDIO/'manifest.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    for i,d in enumerate(LESSONS):
        stem=f"{d['n']:02d}-{d['slug']}"
        for lang in LANGS:
            suffix='' if lang=='ru' else '-'+lang
            (LESSONS_DIR/(stem+suffix+'.md')).write_text(render(d,lang,LESSONS[i+1] if i<7 else None,by_phrase),encoding='utf-8')
            (STATIC/f"map-{d['map']}-{lang}.svg").write_text(svg(d,lang),encoding='utf-8')
    print(f'{len(LESSONS)} lessons, {len(LESSONS)*3} translations, {len(LESSONS)*3} maps, {len(rows)-363} new recordings')

if __name__=='__main__':main()
